export function trendMarkup(D){
 const has=!!D.ratio252,four=!!D.fourEtfStudy;
 const ranges=(kind,active,items)=>items.map(([key,label])=>`<button type="button" data-${kind}-range="${key}"${key===active?' class="active"':''}>${label}</button>`).join('');
 const rankSettings=has?`<label>分位序列<select id="ratioOverlaySeries" aria-label="主图占比分位序列"><option value="all"${four?'':' selected'}>沪深300全方向</option>${four?'<option value="four" selected>头部四只</option><option value="both">两者对照</option>':''}</select></label>${four?'<label>四只规模<select id="fourRatioBasis" aria-label="四只ETF规模口径"><option value="market">市价规模</option><option value="nav">NAV净资产</option></select></label>':''}`:'';
 const ratioMethods=has?`<p id="ratioScopeNote">占比分位固定对应沪深300，与资金范围筛选独立。全方向使用当前存续${D.ratio252.codes.length}只ETF净资产（份额×同日NAV）÷沪深300同日流通市值；不是自由流通、总市值或指数调整市值。</p><p>全方向分位：此前252个交易日、不含当日，采用并列中位排名；窗口不完整则留空。20%/80%只是位置参考，不是买卖阈值。</p>${four?'<p>头部四只固定510300/510310/510330/159919，主口径为份额×同日未复权收盘价，NAV可切换；原平台算法包含当日最后252个日期位置，剔除缺值，用（更低数＋（并列数−1）/2）÷（有效样本数−1）排名。日频先排名，周/月只取期末。</p>':''}<p>分母来自<a href="https://www.sse.com.cn/aboutus/publication/monthly/index/" target="_blank" rel="noopener">上交所统计月报</a>，是按月披露的历史逐日观测。数据日不等于首次披露日；截止日后的缺口不补值。历史首次可得时点未完整重建，当前存续回溯存在幸存者偏差；不是国家队仓位、胜率或可直接交易的信号。</p><p id="ratioLatestSnapshot"></p>${four?'<p class="research-boundary">原片指标指纹尚未精确对齐，披露滞后回测仅为假设敏感性。<a href="hs300_four_etf_backtest.html">打开完整回测研究</a>。</p>':''}`:'';
 return `<section aria-labelledby="trend-title"><div class="section-head trend-section-head"><h2 id="trend-title">资金趋势</h2><span>悬停／点选／方向键读数</span></div>
<div class="chart-shell trend-main"><div class="trend-topline"><div class="segmented" aria-label="资金柱状图时间范围">${ranges('bar','1y',[['60d','3月'],['120d','6月'],['1y','1年'],['2y','2年'],['3y','3年'],['5y','5年']])}</div><p id="barWindow" class="window-label"></p></div>
<div class="trend-actions"><div class="primary-layers"><label><input type="checkbox" id="showCumulative" checked>累计资金</label>${has?'<label><input id="showRatioOverlay" type="checkbox" checked>占比分位</label>':''}</div><details id="chartSettings" class="chart-settings"><summary><span>曲线与口径</span><small id="displaySummary"></small></summary><div class="settings-body"><div class="settings-indices"><div class="settings-label"><b>对照指数</b><button id="clearOverlays" type="button">清空指数</button></div><div id="indexChoices" role="group" aria-label="叠加指数选择"></div></div><div class="settings-fields">${rankSettings}<label>柱形粒度<select id="barGrain" aria-label="资金柱形粒度"><option value="auto">自动</option><option value="d">日</option><option value="w">周合计</option><option value="m">月合计</option></select></label></div><div class="settings-bottom"><small>指数、分位仅作对照，不改变资金统计范围。</small><button id="resetTrendDisplay" type="button">重置显示</button></div></div></details></div>
<div id="barLegend" class="chart-legend" aria-label="资金与指数图例"></div>
<svg id="dailyBarSvg" viewBox="0 0 1080 390" tabindex="0" role="img" aria-label="资金净申赎、累计资金、指数与占比分位" aria-describedby="barTip"><g id="barGrid"></g><g id="bars"></g><g id="indexLines"></g><g id="barCumLines"></g><g id="ratioOverlayLines"></g><g id="barHover" visibility="hidden"></g></svg><div id="barTip" class="chart-tooltip" role="tooltip" aria-label="资金图读数"></div><div id="barReadout" class="chart-readout" aria-live="polite"></div>
<div class="trend-status-row">${has?'<p id="ratioFreshness" class="trend-status"></p>':`<p class="trend-status">资金截至 ${D.asOf}</p>`}<span>金额：亿元 · 分位：0–100%</span></div>
<div id="flowTotals" class="flow-totals" aria-label="所选范围申赎合计"></div><p id="barCoverage" class="coverage-warning"></p>
<p class="trend-short-note">当前存续样本回溯；ETF流量无法按账户归因。各曲线独立刻度，交叉位置不代表大小或因果。</p>
<details id="trendMethod" class="trend-method"><summary>口径、截止日与来源${four?' · 回测研究':''}</summary><div class="method-body"><p id="indexOverlayNote"></p><p id="flowTotalScope"></p><p>申赎金额按官方份额日变化×同日NAV估算，保留份额折算校正；上市初始份额不计净申购。累计从所选窗口起点重新归零，不是账户余额。周/月资金为逐日加总、指数和分位取期末；3/6月按60/120交易日近似，1/2/3/5年按自然年回溯。</p>${ratioMethods}<p>份额：<a href="https://www.sse.com.cn/assortment/fund/etf/list/scale/">上交所</a>／<a href="https://fund.szse.cn/marketdata/fund/list/index.html">深交所</a>；同日NAV与六指数收盘：<a href="https://fund.eastmoney.com/">公开基金／行情源（B）</a>。报告日${D.reportDate}，资金／行情截至${D.asOf}。</p></div></details></div>
<details id="cumPanel" class="detail-box supplementary-view"><summary>独立累计视图（可选）</summary><div class="inner"><div class="chart-shell"><div class="chart-head"><div><h3>累计净申赎</h3><p>亿元 · <span id="cumWindow"></span></p></div><div class="segmented" aria-label="累计曲线时间范围">${ranges('cum','60d',[['10d','10日'],['60d','60日'],['1y','1年'],['2y','2年'],['3y','3年'],['5y','5年']])}</div></div><svg id="cumSvg" viewBox="0 0 1080 390" tabindex="0" role="img" aria-label="累计净申赎曲线" aria-describedby="cumTip"><g id="cumGrid"></g><polygon id="cumArea" class="cum-area"/><polyline id="cumLine" class="cum-line"/><path id="cumPath" class="cum-line"/><g id="cumHover" visibility="hidden"></g></svg><div id="cumTip" class="chart-tooltip" role="tooltip" aria-label="累计图读数"></div><div id="cumReadout" class="chart-readout"></div><p id="cumCoverage" class="coverage-warning"></p><p class="chart-note" id="trendInterpretation"></p></div></div></details></section>`;
}
